const localtunnel = require('localtunnel');

let activeTunnel = null;

async function connect(opts) {
  const port = opts.port || opts.addr || 8081;
  activeTunnel = await localtunnel({ port: port });
  return activeTunnel.url;
}

async function disconnect(publicUrl) {
  if (activeTunnel) {
    activeTunnel.close();
    activeTunnel = null;
  }
}

async function kill() {
  if (activeTunnel) {
    activeTunnel.close();
    activeTunnel = null;
  }
}

